import { prismadb } from "@/lib/prisma";
import { findLeadForAssessment } from "@/lib/assessments";
import { NextResponse } from "next/server";

/**
 * Receives 5GBP / free assessment data and attaches it to the existing lead.
 *
 * Called twice per submission, keyed by `submission_id` (generated by the Wix page and
 * passed through to the Railway app):
 *   1. Wix page, on submit  -> answers + business/contact details.
 *   2. Railway app, once the report is built -> `report_url` (+ optional `report_status`).
 * Either call can arrive first; both upsert the same row.
 */
export async function POST(req: Request) {
  if (!req.headers.get("content-type")?.includes("application/json")) {
    return NextResponse.json({ message: "Invalid content-type" }, { status: 400 });
  }

  const url = new URL(req.url);
  let token: string | null = url.searchParams.get("token");
  if (!token) {
    const authHeader = req.headers.get("authorization");
    if (authHeader?.startsWith("Bearer ")) token = authHeader.split(" ")[1];
  }
  if (!token) {
    return NextResponse.json({ message: "Unauthorized: Missing token" }, { status: 401 });
  }
  const secureToken = process.env.WIX_WEBHOOK_TOKEN || "secure_token_123456";
  if (token.trim() !== secureToken.trim()) {
    return NextResponse.json({ message: "Unauthorized: Invalid credentials" }, { status: 401 });
  }

  try {
    const raw = await req.json();
    const body = raw.data ? raw.data : raw;

    const str = (v: unknown) =>
      typeof v === "string" && v.trim() ? v.trim() : null;

    const email = str(body.email) || str(body.emailInput);
    const submissionId = str(body.submission_id) || str(body.submissionId);
    const reportUrl = str(body.report_url) || str(body.reportUrl);

    if (!submissionId && !email) {
      return NextResponse.json(
        { message: "submission_id or email is required" },
        { status: 400 }
      );
    }

    // Railway callback without a submission_id: attach to this email's latest assessment.
    let existing = submissionId
      ? await prismadb.crm_Assessments.findUnique({ where: { submission_id: submissionId } })
      : null;
    if (!existing && !submissionId && email) {
      existing = await prismadb.crm_Assessments.findFirst({
        where: { email: { equals: email, mode: "insensitive" } },
        orderBy: { submitted_at: "desc" },
      });
    }

    const businessName = str(body.business_name) || str(body.businessName) || str(body.title);
    const postcode = str(body.postcode);
    const contactName = str(body.contact_name) || str(body.namePolicyOwner);
    const answers = body.answers && typeof body.answers === "object" ? body.answers : undefined;

    const reportFields = reportUrl
      ? {
          report_url: reportUrl,
          report_status: str(body.report_status) || "ready",
          report_ready_at: new Date(),
        }
      : str(body.report_status)
        ? { report_status: str(body.report_status)! }
        : {};

    // Only fill in details that were actually sent, so the report callback never blanks
    // fields captured at submission.
    const details = {
      ...(businessName ? { business_name: businessName } : {}),
      ...(contactName ? { contact_name: contactName } : {}),
      ...(email ? { email } : {}),
      ...(str(body.phone) ? { phone: str(body.phone)! } : {}),
      ...(postcode ? { postcode } : {}),
      ...(str(body.website) || str(body.url) ? { website: (str(body.website) || str(body.url))! } : {}),
      ...(str(body.membership_number) || str(body.membershipNumber)
        ? { membership_number: (str(body.membership_number) || str(body.membershipNumber))! }
        : {}),
      ...(str(body.referred_by_rd) ? { referred_by: str(body.referred_by_rd)! } : {}),
      ...(str(body.assessment_type) ? { assessment_type: str(body.assessment_type)! } : {}),
      ...(answers ? { answers } : {}),
    };

    // (Re)try matching whenever the row has no lead yet — the lead sync may have landed
    // after the first attempt.
    let leadId = existing?.lead_id ?? null;
    let matchedBy: string | null = null;
    if (!leadId) {
      const match = await findLeadForAssessment({
        email: email || existing?.email,
        businessName: businessName || existing?.business_name,
        postcode: postcode || existing?.postcode,
      });
      if (match) {
        leadId = match.id;
        matchedBy = match.matchedBy;
      }
    }

    let assessment;
    if (existing) {
      assessment = await prismadb.crm_Assessments.update({
        where: { id: existing.id },
        data: { ...details, ...reportFields, ...(leadId ? { lead_id: leadId } : {}) },
      });
    } else {
      assessment = await prismadb.crm_Assessments.create({
        data: {
          submission_id: submissionId || `auto-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
          ...details,
          ...reportFields,
          lead_id: leadId,
        },
      });
    }

    if (leadId && !existing?.lead_id) {
      await prismadb.sys_audit_logs.create({
        data: {
          entity_type: "crm_Leads",
          entity_id: leadId,
          field_mutated: "ASSESSMENT_RECEIVED",
          new_value: JSON.stringify({ assessment_id: assessment.id, matchedBy }),
        },
      });
    }

    return NextResponse.json(
      {
        message: leadId ? "Assessment recorded against lead" : "Assessment recorded (no lead matched)",
        assessment_id: assessment.id,
        lead_id: leadId,
        matched_by: matchedBy,
        report_url: assessment.report_url,
      },
      { status: existing ? 200 : 201 }
    );
  } catch (error) {
    console.error("Wix assessments webhook error:", error);
    return NextResponse.json({ message: "Internal Server Error" }, { status: 500 });
  }
}
